# Readings made from the images, before the Duska agent's entries were opened.
# (file, DUS id, part, language, title, [(column, original, english, certainty)], translation, notes)
C='clear'; P='probable'; U='uncertain'
R=[]
def r(file,dus,part,lang,title,fields,translation,notes,year_note=None):
    R.append(dict(file=file,dus=dus,part=part,language=lang,title=title,fields=fields,translation=translation,notes=notes,year_note=year_note))
